 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # The sparse zero cells are the image; color their cardinally connected
    # interior component, preserving the ones on the outer margin.
    seen = set()
    stack = []
    for r in range(h):
        for c in range(w):
            if (r == 0 or c == 0 or r == h-1 or c == w-1) and grid[r][c] == 0:
                seen.add((r,c)); stack.append((r,c))
    while stack:
        r,c=stack.pop()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and (nr,nc) not in seen:
                seen.add((nr,nc)); stack.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r,c) not in seen:
                out[r][c] = 3
    return out
