 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    background = counts.most_common(1)[0][0]
    markers = {x for x in counts if x != background}
    out = [row[:] for row in grid]

    # Draw the color-3 segments between consecutive markers in each row.
    for r in range(h):
        points = [c for c in range(w) if grid[r][c] in markers]
        for a, b in zip(points, points[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 3

    # And between consecutive markers in each column.
    for c in range(w):
        points = [r for r in range(h) if grid[r][c] in markers]
        for a, b in zip(points, points[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
